package dev.odin.controls;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;
/** Visibility belongs to Android's channels; hiding status never disables a control lease. */
final class ControlNotifications {
 static final String FAN="fan",LED="ring-segments",CPU="performance",RECOVERY="recovery-alerts";
 static final int FAN_ALERT=101,CPU_ALERT=103,LED_ALERT=106;
 static void ensure(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);channel(n,FAN,"Fan status",NotificationManager.IMPORTANCE_LOW);channel(n,LED,"LED status",NotificationManager.IMPORTANCE_LOW);channel(n,CPU,"CPU/GPU status",NotificationManager.IMPORTANCE_LOW);channel(n,RECOVERY,"Recovery alerts",NotificationManager.IMPORTANCE_DEFAULT);}
 static void channel(NotificationManager n,String id,String name,int importance){NotificationChannel existing=n.getNotificationChannel(id);if(existing==null){existing=new NotificationChannel(id,name,importance);existing.setShowBadge(false);}else{if(name.contentEquals(existing.getName()))return;existing.setName(name);}n.createNotificationChannel(existing);}
 static String visibility(Context c,String id){ensure(c);NotificationManager n=c.getSystemService(NotificationManager.class);int importance=n.getNotificationChannel(id).getImportance();if(!n.areNotificationsEnabled()||importance==NotificationManager.IMPORTANCE_NONE)return "Hidden";if(importance==NotificationManager.IMPORTANCE_MIN)return "Minimized";return importance<=NotificationManager.IMPORTANCE_LOW?"Silent":"Visible";}
 static Intent settings(Context c,String id){ensure(c);return new Intent(Settings.ACTION_CHANNEL_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,c.getPackageName()).putExtra(Settings.EXTRA_CHANNEL_ID,id);}
 static Notification.Builder status(Context c,String channel,String title,String text){return new Notification.Builder(c,channel).setSmallIcon(c.getResources().getIdentifier("ic_notification","drawable",c.getPackageName())).setContentTitle(title).setContentText(text).setCategory(Notification.CATEGORY_SERVICE).setPriority(Notification.PRIORITY_LOW).setOnlyAlertOnce(true).setShowWhen(false);}
 static void recovery(Context c,int id,String title,String text){ensure(c);String tab=id==CPU_ALERT?"Performance":id==LED_ALERT?"LEDs":"Fan";PendingIntent open=PendingIntent.getActivity(c,id,new Intent(c,MainActivity.class).putExtra("openTab",tab),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notice=new Notification.Builder(c,RECOVERY).setSmallIcon(c.getResources().getIdentifier("ic_notification","drawable",c.getPackageName())).setContentTitle(title).setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setCategory(Notification.CATEGORY_ERROR).setContentIntent(open).setAutoCancel(true).build();try{c.getSystemService(NotificationManager.class).notify(id,notice);}catch(SecurityException denied){android.util.Log.w("RavenRecovery","Recovery completed; Android blocked its alert",denied);}}
 static void clear(Context c,int id){c.getSystemService(NotificationManager.class).cancel(id);}
}
